 if len(s.OneOf)>0 {matches:=0;for _,v:=range s.OneOf{if validateNode(v,raw,path)==nil{matches++}};if matches!=1{return fail("oneOf requires exactly one matching variant")}}
 if len(s.AnyOf)>0 {matches:=0;for _,v:=range s.AnyOf{if validateNode(v,raw,path)==nil{matches++}};if matches==0{return fail("no anyOf variant matches")}}
 for _,v:=range s.AllOf{if err:=validateNode(v,raw,path);err!=nil{return err}}
