 if len(s.Const)>0&&canonical(s.Const)!=canonical(raw){return fail("const mismatch")}
 if len(s.Enum)>0 {found:=false;for _,v:=range s.Enum{if canonical(v)==canonical(raw){found=true}};if !found{return fail("enum mismatch")}}
