  for i,v:=range items{if len(s.Items)>0 {if err:=validateNode(s.Items,v,fmt.Sprintf("%s[%d]",path,i));err!=nil{return err}};if s.Unique{key:=canonical(v);if seen[key]{return fail("duplicate item")};seen[key]=true}}
